const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Point([-90.0490, 35.1495]).buffer(15000); // Memphis, TN, 15km buffer
    const date2019 = ee.Date('2019-02-25');
    const date2014 = ee.Date('2014-02-27');

    // Function to mask clouds in Landsat 8 C2 L2
    function maskL8sr(image) {
        // Bit 3 is cloud, Bit 4 is cloud shadow.
        const cloudShadowBitMask = (1 << 4);
        const cloudsBitMask = (1 << 3);
        const qa = image.select('QA_PIXEL');
        // Both flags should be set to 0, indicating clear conditions.
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
            .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
        return image.updateMask(mask);
    }

    // Function to calculate MNDWI
    function addMNDWI(image) {
        // Landsat 8: Green = B3, SWIR1 = B6
        const mndwi = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
        return image.addBands(mndwi);
    }

    // Function to process and calculate water area
    async function getWaterArea(date, collectionName) {
        let collection = ee.ImageCollection(collectionName)
            .filterBounds(aoi)
            .filterDate(date.advance(-2, 'day'), date.advance(2, 'day'));

        const imageCount = collection.size().getInfo();
        if (imageCount === 0) {
            return { area: null, count: 0, cloud: -1, status: 'C1' };
        }

        const image = collection.sort('CLOUD_COVER').first();
        const cloudCover = image.get('CLOUD_COVER').getInfo();
        const processedImage = addMNDWI(maskL8sr(image));
        const waterMask = processedImage.select('MNDWI').gt(0); // MNDWI > 0 is water

        // Calculate the number of water pixels
        const stats = waterMask.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: aoi,
            scale: 30, // Native resolution for Landsat
            maxPixels: 1e9
        });

        const waterPixels = stats.get('MNDWI').getInfo();

        if (waterPixels === null) {
            return { area: null, count: -1, cloud: cloudCover, status: 'C3' };
        }
        if (waterPixels === 0) {
             return { area: 0, count: waterPixels, cloud: cloudCover, status: 'C2_CHECK' }; // May be valid zero or masked out
        }

        // Each pixel is 30x30m, so area is pixels * 900.
        return { area: waterPixels * 900, count: waterPixels, cloud: cloudCover, status: 'OK' };
    }

    // 2. Data Acquisition and Processing
    const l8CollectionName = 'LANDSAT/LC08/C02/T1_L2';
    const water2019 = await getWaterArea(date2019, l8CollectionName);
    const water2014 = await getWaterArea(date2014, l8CollectionName);

    // 3. Validation & Final Answer
    if (water2019.status === 'C1' || water2014.status === 'C1') {
        console.log(`Image collection for 2019 empty: ${water2019.status === 'C1'}`);
        console.log(`Image collection for 2014 empty: ${water2014.status === 'C1'}`);
        console.log("C1: Empty Collection");
        return;
    }
     if (water2019.status === 'C2_CHECK' && water2014.status === 'C2_CHECK') {
        console.log('2019 Water Pixels: 0');
        console.log('2014 Water Pixels: 0');
        console.log("C2: No Valid Pixels");
        return;
    }
     if (water2019.status === 'C3' || water2014.status === 'C3') {
        console.log(`Calculation failed for 2019: ${water2019.status === 'C3'}`);
        console.log(`Calculation failed for 2014: ${water2014.status === 'C3'}`);
        console.log("C3: Calculation Failure");
        return;
    }

    const area2019_km2 = water2019.area / 1e6;
    const area2014_km2 = water2014.area / 1e6;

    console.log(`2019-02-25 Water Area: ${area2019_km2.toFixed(2)} km2 (Pixels: ${water2019.count}, Cloud: ${water2019.cloud.toFixed(2)}%)`);
    console.log(`2014-02-27 Water Area: ${area2014_km2.toFixed(2)} km2 (Pixels: ${water2014.count}, Cloud: ${water2014.cloud.toFixed(2)}%)`);

    if (area2019_km2 > area2014_km2) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during GEE initialization or execution:', e);
        console.log("D");
    }
}

initEE();
